<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Servers; use Illuminate\Support\Facades\Log; use Pterodactyl\Models\Server; use Pterodactyl\Services\Dezerx\Demo; use Pterodactyl\Services\Dezerx\Billing\Billing; use Pterodactyl\Services\Dezerx\Billing\BillingClient; use Pterodactyl\Services\Dezerx\Billing\DemoBilling; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Pterodactyl\Http\Requests\Api\Client\Servers\GetServerRequest; use Symfony\Component\HttpKernel\Exception\ServiceUnavailableHttpException; class BillingController extends ClientApiController { public function __construct(private BillingClient $client) { parent::__construct(); } public function __invoke(GetServerRequest $request, Server $server): array { if (Demo::is($request->user())) { return ['object' => 'billing', 'attributes' => DemoBilling::record()]; } if (!Billing::configured()) { return ['object' => 'billing', 'attributes' => null]; } try { $subscription = $this->client->subscription($server); } catch (\RuntimeException $exception) { Log::warning('Billing lookup failed for server ' . $server->uuid . ': ' . $exception->getMessage()); throw new ServiceUnavailableHttpException(null, 'The billing system could not be reached right now.'); } return [ 'object' => 'billing', 'attributes' => $subscription, ]; } } 